const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => localStorage.getItem('a2-interface-language') || 'de');

  useEffect(() => {
    localStorage.setItem('a2-interface-language', language);
    document.documentElement.lang = language === 'zh' ? 'zh-CN' : language === 'ja' ? 'ja-JP' : language;
  }, [language]);

  const value = useMemo(() => ({
    language,
    setLanguage,
    locale: { de: 'de-DE', en: 'en-GB', es: 'es-ES', tr: 'tr-TR', zh: 'zh-CN', ja: 'ja-JP' }[language],
    t(key, values = {}) {
      const template = translations[language]?.[key] ?? de[key] ?? key;
      return Object.entries(values).reduce((text, [name, replacement]) => text.replaceAll(`{${name}}`, replacement), template);
    }
  }), [language]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  return useContext(LanguageContext);
}
